using System;using System.IO;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {
 [Serializable]public sealed class ModuleCancelFixture{public string initial;public StateData before,after,cancelActive;}
 public sealed class ModuleCancelTests {
 [Test]public void QueuedRefundMatchesSourceAndOldClickCannotRefundAnotherJob(){var f=JsonUtility.FromJson<ModuleCancelFixture>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/ModuleCancelReference.json")));var s=UnityWebImport.Validate(f.initial);for(int i=0;i<3;i++)s=Workshop.StartModule(s,i%2);Assert.That(s.Prestige.moduleQueue.Length,Is.EqualTo(2));long ticket=s.Workshop.revision;var next=Workshop.CancelModule(s,0,ticket);Assert.That(next.Workshop.components,Is.EqualTo(f.after.workshop.components));Assert.That(next.Data.CompareTo(ScientificNumber.FromData(f.after.data)),Is.Zero);Assert.That(next.Prestige.moduleQueue.Length,Is.EqualTo(f.after.prestige.moduleQueue.Length));Assert.That(next.Workshop.moduleJob.id,Is.EqualTo(f.cancelActive.workshop.moduleJob.id));Assert.That(Workshop.CancelModule(next,0,ticket),Is.SameAs(next));Assert.That(Workshop.CancelModule(next,-1),Is.SameAs(next));Assert.That(next.Lifetime.componentsEarned,Is.EqualTo(s.Lifetime.componentsEarned),"Refund is not a new component reward");var codec=new UnitySaveCodec();var reload=codec.Decode(codec.Encode(StateData.From(next)),AtomicSaveStore.Version).ToState();Assert.That(reload.Prestige.moduleQueue.Length,Is.EqualTo(1));}
 }
}
